+    async generateLineItemsForEnrollment({
+        enrollmentRes,
+        businessID,
+        readSettingsResponseData,
+        startDate,
+        endDate,
+        customer,
+        lineItems,
+    }: {
+        enrollmentRes: CustomerEnrollmentResponseData;
+        businessID: string;
+        readSettingsResponseData: ReadSettingsResponseData;
